def clause_problems(low):
    """R2-05: a positive phrase sitting INSIDE a negative phrase does not count.
    'Do not use when auditing' contains 'use when' at offset 7 - comparing
    start offsets misses that, so span containment is what we test."""
    out = []
    neg_spans = []
    for n in NEGATIVE:
        start = low.find(n)
        while start != -1:
            neg_spans.append((start, start + len(n)))
            start = low.find(n, start + 1)

    def inside_negative(i, j):
        return any(a <= i and j <= b for a, b in neg_spans)

    pos_found = False
    for p in POSITIVE:
        start = low.find(p)
        while start != -1:
            if not inside_negative(start, start + len(p)):
                pos_found = True
                break
            start = low.find(p, start + 1)
        if pos_found:
            break

    if not pos_found:
        out.append("no standalone positive clause ('Use when ...') - "
                   "Claude will not trigger (a 'use when' inside 'do not use when' does not count)")
    if not neg_spans:
        out.append("no negative clause ('Do not use ...') - Codex over-fires")
    return out

