     1	function Sync-Repo($path, $branch) {
     2	    $name = Split-Path $path -Leaf
     3	    if ($path -eq "$U/.claude") { $name = 'dotclaude' }
     4	    if (-not (Test-Path (Join-Path $path '.git'))) { $Errors.Add("repo-missing:$name"); return }
     5	    Push-Location $path
     6	    try {
     7	        git fetch origin 2>&1 | Out-Null
     8	        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
     9	        $behind = 0; $ahead = 0
    10	        if ($counts) { $p = $counts -split '\s+'; $behind = [int]$p[0]; $ahead = [int]$p[1] }
    11	        $dirty = (git status --porcelain | Measure-Object).Count
    12	
    13	        if ($behind -gt 0 -and ($ahead -gt 0 -or $dirty -gt 0)) {
    14	            # Diverged with local changes: never merge blindly from automation.
    15	            $Errors.Add("repo-diverged:$name")
    16	            Log "REPO $name : DIVERGED (behind=$behind ahead=$ahead dirty=$dirty) - manual reconcile needed"
    17	            return
    18	        }
    19	        if ($behind -gt 0) {
    20	            if (-not $DryRun) { git pull --ff-only origin $branch 2>&1 | Out-Null }
    21	            Log "REPO $name : $(if ($DryRun) { '[dry-run] would fast-forward' } else { 'fast-forwarded' }) $behind commit(s)"
    22	        }
    23	        if ($dirty -gt 0) {
    24	            if (-not $DryRun) {
    25	                git add -A 2>&1 | Out-Null
    26	                git commit -m ("chore: daily backup sync {0} [auto]" -f (Get-Date -Format 'yyyy-MM-dd')) 2>&1 | Out-Null
    27	            }
    28	            Log "REPO $name : $(if ($DryRun) { '[dry-run] would commit' } else { 'committed' }) $dirty change(s)"
    29	        }
    30	        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
    31	        $ahead = if ($counts) { [int](($counts -split '\s+')[1]) } else { 0 }
    32	        if ($DryRun -and $dirty -gt 0) { $ahead = 1 }
    33	        if ($ahead -gt 0) {
    34	            if (-not $DryRun) {
    35	                # Capture push output instead of discarding it. Scheduled runs have failed
    36	                # to push for weeks with no recorded reason (2026-09-02 handoff); Out-Null
    37	                # threw the error text away. Success stays silent - only failures log.
    38	                $pushOut = git push origin $branch 2>&1
    39	                if ($LASTEXITCODE -ne 0) {
    40	                    $Errors.Add("repo-push:$name")
    41	                    Log "REPO $name : PUSH FAILED"
    42	                    foreach ($l in $pushOut) { if ("$l".Trim()) { Log "REPO $name : PUSH ERR | $l" } }
    43	                    return
    44	                }
    45	            }
    46	            Log "REPO $name : $(if ($DryRun) { '[dry-run] would push' } else { 'pushed' })"
    47	        }
    48	        $Results.Add(@{ kind='repo'; name=$name; status='OK' })
    49	    } finally { Pop-Location }
